import {test,expect} from '@playwright/test';
import {PDFDocument,StandardFonts,rgb,degrees} from 'pdf-lib';
import * as mupdf from 'mupdf';
import JSZip from 'jszip';
import fs from 'node:fs/promises';
import {splitGroups,watermarkObject} from '../src/document-tools.js';
async function fixture(){const d=await PDFDocument.create(),font=await d.embedFont(StandardFonts.Helvetica);for(let i=0;i<3;i++){const p=d.addPage([595,842]);p.drawText(`Page ${i+1} original content`,{x:60,y:720,size:20,font});if(i===1)p.setRotation(degrees(90));}return Buffer.from(await d.save());}
async function upload(page,bytes=undefined){await page.goto('/');await page.locator('#file').setInputFiles({name:'tools.pdf',mimeType:'application/pdf',buffer:bytes||await fixture()});await expect(page.locator('#document')).toBeVisible();await expect(page.locator('#busy')).toBeHidden();}
async function download(page,selector){const event=page.waitForEvent('download');await page.locator(selector).click();const d=await event;await expect(page.locator('#busy')).toBeHidden();return fs.readFile(await d.path());}
function text(bytes){const d=mupdf.Document.openDocument(new Uint8Array(bytes),'application/pdf');const texts=[];for(let i=0;i<d.countPages();i++){const p=d.loadPage(i),s=p.toStructuredText();texts.push(s.asText());s.destroy();p.destroy();}d.destroy();return texts;}
test('watermark all pages, replace selected range, undo and project reopen',async({page})=>{
await upload(page);await page.locator('[data-tab=tools]').click();await page.locator('#watermarktool').click();await page.locator('#wmtext').fill('GİZLİ — ÖRNEK');await page.locator('#applywatermark').click();await expect(page.locator('#modal')).not.toBeVisible();await page.locator('#export').click();let bytes=await download(page,'#downloadnow');expect(text(bytes)).toHaveLength(3);for(const t of text(bytes))expect(t).toContain('GİZLİ');
await page.locator('#watermarktool').click();await page.locator('#wmtext').fill('ONAYLANDI');await page.locator('#wmpages').fill('2');await page.locator('#applywatermark').click();await page.locator('#export').click();bytes=await download(page,'#downloadnow');expect(text(bytes)[0]).toContain('GİZLİ');expect(text(bytes)[1]).toContain('ONAYLANDI');expect(text(bytes)[1]).not.toContain('GİZLİ');await page.locator('#undo').click();
const project=await download(page,'#project');const parsed=JSON.parse(project);expect(parsed.state.pages.every(p=>p.objects.filter(o=>o.watermark).length===1)).toBe(true);await page.reload();await page.locator('#file').setInputFiles({name:'saved.ekopdf',mimeType:'application/json',buffer:project});await expect(page.locator('#busy')).toBeHidden();await expect(page.locator('[data-page]')).toHaveCount(3);
});
test('split custom groups preserves order, text and rotation',async({page})=>{
await upload(page);await page.locator('[data-tab=tools]').click();await page.locator('#splittool').click();await page.locator('#splitmode').selectOption('custom');await page.locator('#splitcustom').fill('1,3; 2');await expect(page.locator('#splitpreview')).toContainText('2 PDF');const zip=await JSZip.loadAsync(await download(page,'#downloadsplit'));const files=Object.values(zip.files).filter(f=>!f.dir);expect(files).toHaveLength(2);const first=await files[0].async('uint8array'),second=await files[1].async('uint8array');expect(text(first)[0]).toContain('Page 1');expect(text(first)[1]).toContain('Page 3');expect(text(second)[0]).toContain('Page 2');expect((await PDFDocument.load(second)).getPage(0).getRotation().angle).toBe(90);
});
test('lossless compression keeps native text and reports actual byte sizes',async({page})=>{
await upload(page);await page.locator('[data-tab=tools]').click();await page.locator('#compresstool').click();await page.locator('#runcompress').click();await expect(page.locator('#downloadcompressed')).toBeVisible();await expect(page.locator('#compressresult')).toContainText('KB');const bytes=await download(page,'#downloadcompressed');expect(text(bytes).join(' ')).toContain('Page 3 original content');expect((await PDFDocument.load(bytes)).getPageCount()).toBe(3);
});
test('raster compression shrinks image-heavy PDF and retains page dimensions',async({page})=>{
await page.goto('/');const png=await page.evaluate(async()=>{const c=document.createElement('canvas');c.width=1800;c.height=2400;const ctx=c.getContext('2d');const pixels=ctx.createImageData(c.width,c.height);let seed=17;for(let i=0;i<pixels.data.length;i+=4){seed=(seed*1664525+1013904223)>>>0;const n=seed%44;pixels.data[i]=210+n;pixels.data[i+1]=204+n;pixels.data[i+2]=195+n;pixels.data[i+3]=255;}ctx.putImageData(pixels,0,0);ctx.fillStyle='#193d2c';ctx.font='48px sans-serif';for(let i=0;i<35;i++)ctx.fillText('Image-heavy compression sample '+i,80,100+i*60);return c.toDataURL('image/png').split(',')[1];});const d=await PDFDocument.create(),img=await d.embedPng(Buffer.from(png,'base64'));d.addPage([595,842]).drawImage(img,{x:0,y:0,width:595,height:842});await upload(page,Buffer.from(await d.save()));await page.locator('[data-tab=tools]').click();await page.locator('#compresstool').click();await page.locator('#compressmode').selectOption('small');await expect(page.locator('#compressdescription')).toContainText('Metin seçimi');await page.locator('#runcompress').click();await expect(page.locator('#downloadcompressed')).toBeVisible();await expect(page.locator('#compressresult')).toContainText('daha küçük');const bytes=await download(page,'#downloadcompressed');expect(bytes.length).toBeLessThan((await d.save()).length);expect((await PDFDocument.load(bytes)).getPage(0).getWidth()).toBe(595);
});
test('typed Turkish signature and logo watermark are exported and can be reopened',async({page})=>{
await upload(page);await page.locator('[data-tab=sign]').click();await page.locator('#typedsignature').click();await page.locator('#signname').fill('Çağrı Şen — İmza');await page.locator('#signstyle').selectOption('bolditalic');await page.locator('#addtypedsign').click();await page.locator('[data-tab=tools]').click();await page.locator('#watermarktool').click();await page.locator('#wmtype').selectOption('image');const png=Buffer.from(await page.evaluate(()=>{const c=document.createElement('canvas');c.width=240;c.height=100;const x=c.getContext('2d');x.fillStyle='#187353';x.fillRect(0,0,240,100);x.fillStyle='white';x.font='30px sans-serif';x.fillText('ekoPDF',20,60);return c.toDataURL('image/png').split(',')[1];}),'base64');await page.locator('#wmimage').setInputFiles({name:'logo.png',mimeType:'image/png',buffer:png});await expect(page.locator('#wmpreview')).toBeVisible();await page.locator('#applywatermark').click();await page.locator('#export').click();const bytes=await download(page,'#downloadnow');expect(text(bytes)[0]).toContain('Çağrı Şen');expect((await PDFDocument.load(bytes)).getPageCount()).toBe(3);
});
test('split validation and rotated watermark geometry',()=>{expect(()=>splitGroups(3,'custom',1,'1-4')).toThrow();expect(()=>splitGroups(3,'custom',1,'1;;2')).toThrow();expect(splitGroups(5,'size',2)).toEqual([[0,1],[2,3],[4]]);for(const rotation of [0,90,180,270]){const p={w:595,h:842,rotation};const o=watermarkObject(p,{text:'TEST',size:44,angle:-35,position:'center'},()=>200);expect(o.angle+rotation).toBe(-35);expect(Number.isFinite(o.x)&&Number.isFinite(o.y)).toBe(true);}});
test('demo watermark project roundtrip and invalid watermark leaves document untouched',async({page})=>{await page.goto('/');await page.locator('#demo').click();await page.locator('[data-tab=tools]').click();await page.screenshot({path:'test-results/document-tools.png'});await page.locator('#watermarktool').click();await page.locator('#wmtext').fill('');await page.locator('#applywatermark').click();await expect(page.locator('#toast')).toContainText('Filigran metni');await expect(page.locator('#modal')).toBeVisible();await page.locator('#wmtext').fill('ÖRNEK BELGE');await page.screenshot({path:'test-results/watermark-dialog.png'});await page.locator('#applywatermark').click();const project=await download(page,'#project');await page.reload();await page.locator('#file').setInputFiles({name:'demo.ekopdf',mimeType:'application/json',buffer:project});await expect(page.locator('#busy')).toBeHidden();await expect(page.locator('[data-page]')).toHaveCount(2);});
